INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(15401, 'Psalms 149:4', 'Psalms', 149, 4, '&nbsp;ځکه چې مالِک خُدائ د خپلو خلقو سره خوشحاليږى، او هغه عاجزانو ته د خلاصون تاج ورپه سروى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15402, 'Psalms 149:5', 'Psalms', 149, 5, '&nbsp;مقدسين دې د هغۀ په عزت ورکولو سره خوشحاله شى، او په خپلو بسترو کښې دې د خوشحالۍ سندرې وائى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15403, 'Psalms 149:6', 'Psalms', 149, 6, '&nbsp;د خُدائ پاک ثناء صِفت دې د هغوئ په خُلو وى او دوه مخيزه تُوره دې د هغوئ په لاسونو کښې وى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15404, 'Psalms 149:7', 'Psalms', 149, 7, '&nbsp;ترڅو په زور سره د قومونو نه بدل واخلى، او چې د هغوئ خلقو ته سزا ورکړى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15405, 'Psalms 149:8', 'Psalms', 149, 8, '&nbsp;چې د هغوئ بادشاهان په هتکړُو کښې وتړى او د هغوئ مشران دې په بيړو کښې وتړى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15406, 'Psalms 149:9', 'Psalms', 149, 9, '&nbsp;او چې څنګه فېصله د هغوئ په خلاف ليکلے شوې ده هغه شان وشى. دا د هغۀ ټولو مقدسينو ته جلال دے. د مالِک خُدائ ثناء صِفت دې وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15407, 'Psalms 150:1', 'Psalms', 150, 1, '&nbsp;د مالِک خُدائ ثناء ووايئ. د هغۀ په مقدس ځائ کښې د هغۀ ثناء ووايئ، د هغۀ په زورَور آسمان کښې د هغۀ ثناء صِفت وکړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15408, 'Psalms 150:2', 'Psalms', 150, 2, '&nbsp;د هغۀ د لويو کارونو په وجه د هغۀ ثناء صِفت وکړئ، او د هغۀ د بې‌حده لويوالى په اندازه د هغۀ ثناء صِفت وکړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15409, 'Psalms 150:3', 'Psalms', 150, 3, '&nbsp;او د بيګل د آواز سره د هغۀ ثناء خوان شئ، د رباب او بينجو د ساز سره د هغۀ ثناء صِفت وکړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15410, 'Psalms 150:4', 'Psalms', 150, 4, '&nbsp;د تمبل او ګډا سره د هغۀ ثناء صِفت وکړئ، په شپيلۍ او د رباب تارونو سره د هغۀ ثناء صِفت وکړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15411, 'Psalms 150:5', 'Psalms', 150, 5, '&nbsp;د چمټو او تاليو سره د هغۀ ثناء صِفت وکړئ، د هغۀ ثناء صِفت د تاليو په شرنګار کښې وکړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15412, 'Psalms 150:6', 'Psalms', 150, 6, '&nbsp;هر يو ساه لرونکے دې د مالِک خُدائ ثناء صِفت وکړى، د مالِک خُدائ ثناء صِفت وکړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15413, 'Proverbs 1:1', 'Proverbs', 1, 1, '&nbsp;د داؤد د زوئ د سليمان متلونه چې د بنى اِسرائيلو بادشاه وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15414, 'Proverbs 1:2', 'Proverbs', 1, 2, '&nbsp;د دوئ مقصد دا دے چې خلقو ته د حِکمت او تربيت په حقله تعليم ورکړى او چې هغوئ په عقلمندو خبرو پوهه شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15415, 'Proverbs 1:3', 'Proverbs', 1, 3, '&nbsp;دا به تاسو ته تعليم درکړى چې څنګه به خپل ژوند په صداقت، عدل او اِنصاف سره تېروئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15416, 'Proverbs 1:4', 'Proverbs', 1, 4, '&nbsp;دا متلونه ساده خلق هوښياروى او ځوانانو له عقل او تميز ورکوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15417, 'Proverbs 1:5', 'Proverbs', 1, 5, '&nbsp;دا متلونه د هوښيارانو پوهه نوره هم زياتوى او د عالِم رهنمائى کوى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15418, 'Proverbs 1:6', 'Proverbs', 1, 6, '&nbsp;نو هغوئ به په متلونو او مِثالونو او د هوښيارانو په خبرو او د هغوئ په معماګانو دواړو به پوهه شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15419, 'Proverbs 1:7', 'Proverbs', 1, 7, '&nbsp;د مالِک خُدائ يره د عِلم شروع ده، خو کم عقل خلق د حِکمت او تربيت سپکاوے کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15420, 'Proverbs 1:8', 'Proverbs', 1, 8, '&nbsp;زما زويه، د خپل پلار لارښودنو ته غوږ شه او د خپلې مور تعليم دې مۀ هېروه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15421, 'Proverbs 1:9', 'Proverbs', 1, 9, '&nbsp;د هغوئ نصيحتونه به ستا د سر دپاره ښائسته سهره او ستا د غاړې دپاره د عزت هار وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15422, 'Proverbs 1:10', 'Proverbs', 1, 10, '&nbsp;زما زويه، کله چې ګناهګاران ستا د بې‌لارې کولو کوشش کوى، نو د هغوئ نه ځان ساته.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15423, 'Proverbs 1:11', 'Proverbs', 1, 11, '&nbsp;کۀ چرې هغوئ ووائى، ”راځه، چې يو ځائ شُو او د پټ ځائ نه ګزار وکړُو او قتل وکړُو. راځه چې په يو بې‌ګناه کس باندې هسې د خوند دپاره غلې حمله وکړُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15424, 'Proverbs 1:12', 'Proverbs', 1, 12, '&nbsp;راځه چې د قبر په شان هغوئ ژوندى تېر کړُو، د هغوئ په شان لکه څوک چې د مرګ کندې ته کوزيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15425, 'Proverbs 1:13', 'Proverbs', 1, 13, '&nbsp;مونږ به هر قِسمه قيمتى څيزونه حاصل کړُو او د لوټ د مال نه به خپل کورونه ډک کړُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15426, 'Proverbs 1:14', 'Proverbs', 1, 14, '&nbsp;راځه مونږ سره ملګرے شه او مونږ چې څۀ لوټ کړُو نو په هغې کښې به تا له هم برخه درکړُو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15427, 'Proverbs 1:15', 'Proverbs', 1, 15, '&nbsp;زما زويه، د داسې خلقو سره مۀ ځه، او د هغوئ په نقش قدم مۀ ځه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15428, 'Proverbs 1:16', 'Proverbs', 1, 16, '&nbsp;ځکه چې هغوئ د بدکارۍ طرف ته په منډه روان وى، او د وينې تويولو په اړخ تېزۍ سره روان وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15429, 'Proverbs 1:17', 'Proverbs', 1, 17, '&nbsp;د يو مارغۀ د سترګو د وړاندې جال خورول څومره بې‌فائدې دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15430, 'Proverbs 1:18', 'Proverbs', 1, 18, '&nbsp;خو دغه شان خلق د خپل ځان دپاره دام خوروى، داسې دام چې هغوئ به په خپله په کښې تباه شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15431, 'Proverbs 1:19', 'Proverbs', 1, 19, '&nbsp;هم دغه به وى اَنجام د هغه کسانو څوک چې د ناجائزه ‎پېسو ګټلو لالچى وى نو په دې وجه به د خپل ژوند نه لاس ووينځى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15432, 'Proverbs 1:20', 'Proverbs', 1, 20, '&nbsp;حِکمت په لارو کوڅو کښې په تېزه چغې وهى، او په چوکونو کښې په اوچت آواز نعرې وهى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15433, 'Proverbs 1:21', 'Proverbs', 1, 21, '&nbsp;د بازار په ګڼه کښې هغه چغې وهى، او د ښار په دروازو کښې چرته چې خلق راغونډيږى هلته تقرير کوى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15434, 'Proverbs 1:22', 'Proverbs', 1, 22, '&nbsp;”جاهله خلقو، تاسو به تر کومې پورې ساده ګان يئ؟ ترڅو پورې به تاسو مسخره کوونکى په خپلو مسخرو کښې خوشحاله يئ؟ ترڅو پورې به تاسو بې‌وقوفان عِلم نه نفرت کوئ؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15435, 'Proverbs 1:23', 'Proverbs', 1, 23, '&nbsp;راشئ او زما سختې خبرې واورئ. زۀ به خپل زړۀ نه تاسو خبر کړم او تاسو به هوښيار کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15436, 'Proverbs 1:24', 'Proverbs', 1, 24, '&nbsp;ما تاسو ته څو ځله آوازونه وکړل خو تاسو رانۀ غلئ. زۀ تاسو له درغلم خو تاسو ما ته توجو رانۀ کړه،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15437, 'Proverbs 1:25', 'Proverbs', 1, 25, '&nbsp;تاسو زما ټول نصيحتونه نظر انداز کړل او زما اصلاح کول مو رد کړل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15438, 'Proverbs 1:26', 'Proverbs', 1, 26, '&nbsp;خو چې کله تاسو په تکليف کښې پرېوځئ نو زۀ به په تاسو پورې ملنډې کوم، او زۀ به تاسو پورې خندا کوم کله چې تاسو بدبختى راګېر کړى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15439, 'Proverbs 1:27', 'Proverbs', 1, 27, '&nbsp;کله چې بدبختى لکه د طوفان درباندې راشى، او چې مصيبت لکه د سيلۍ په شان درباندې راشى او چې مصيبت او سختى په تاسو باندې غالبه شى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15440, 'Proverbs 1:28', 'Proverbs', 1, 28, '&nbsp;نو بيا چې کله دوئ ما ته چغې وهى، خو زۀ به دوئ له جواب نۀ ورکوم. دوئ به ما هر چرته د زړۀ نه ولټوى، خو دوئ به ما پېدا نۀ کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15441, 'Proverbs 1:29', 'Proverbs', 1, 29, '&nbsp;ځکه چې دوئ د پوهې نه نفرت کولو او دوئ د مالِک خُدائ نه نۀ يرېدل خوښ کړل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15442, 'Proverbs 1:30', 'Proverbs', 1, 30, '&nbsp;دوئ زما نصيحت رد کړو، کله چې مې اصلاح کوله نو دوئ ما ته هيڅ توجو رانۀ کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15443, 'Proverbs 1:31', 'Proverbs', 1, 31, '&nbsp;نو په دې وجه دوئ به د خپل چال چلن ترخه مېوه وخورى او په خپلو منصوبو به ماړۀ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15444, 'Proverbs 1:32', 'Proverbs', 1, 32, '&nbsp;د ساده خلقو سرکشى به دوئ مړۀ کړى، کم عقلان د خپل قناعت په وجه تباه کيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15445, 'Proverbs 1:33', 'Proverbs', 1, 33, '&nbsp;خو هر څوک چې ما ته غوږ نيسى نو هغه به په امن کښې اوسيږى، او د نقصان څۀ يره به پرې نۀ وى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15446, 'Proverbs 2:1', 'Proverbs', 2, 1, '&nbsp;زما زويه، کۀ تۀ زما خبرې ومنې او زما حُکمونه په زړۀ کښې محفوظ کړې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15447, 'Proverbs 2:2', 'Proverbs', 2, 2, '&nbsp;او د عقل خبرو ته غوږ ونيسې او خپل زړۀ د هوښيارتيا طرف ته مائل کړې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15448, 'Proverbs 2:3', 'Proverbs', 2, 3, '&nbsp;نو بيا د پوهې طلب کوه او د حِکمت دپاره په تېزه نعرې ووهه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15449, 'Proverbs 2:4', 'Proverbs', 2, 4, '&nbsp;تۀ د دوئ داسې تلاش وکړه لکه د سپينو زرو چې کوې او يا يې داسې لټون وکړه لکه چې د پټې خزانې کوې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15450, 'Proverbs 2:5', 'Proverbs', 2, 5, '&nbsp;نو بيا به تۀ د مالِک خُدائ په يره باندې پوهه شې او د خُدائ پاک عِلم به حاصل کړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15451, 'Proverbs 2:6', 'Proverbs', 2, 6, '&nbsp;ځکه چې مالِک خُدائ عقل او حِکمت ورکوى، او د هغۀ د خولې نه عِلم او پوهه راوځى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15452, 'Proverbs 2:7', 'Proverbs', 2, 7, '&nbsp;هغه د نېکو خلقو دپاره د عقلمندۍ خزانې ساتى، هغه د هغه چا دپاره ډال دے د چا کردار چې بې‌داغه وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15453, 'Proverbs 2:8', 'Proverbs', 2, 8, '&nbsp;هغه د اِنصاف کوونکو د لارو ساتنه کوى او هغه د خپلو مقدسينو حفاظت کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15454, 'Proverbs 2:9', 'Proverbs', 2, 9, '&nbsp;نو تۀ به په دې پوهه شې چې څۀ ښۀ او د اِنصاف او مناسب دى. او تۀ به د ژوند نېغه لار بيامومې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15455, 'Proverbs 2:10', 'Proverbs', 2, 10, '&nbsp;نو تۀ به عقلمند شې او ستا عِلم او پوهه به ستا روح ته خوشحالى ورکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15456, 'Proverbs 2:11', 'Proverbs', 2, 11, '&nbsp;تميز به په تا نظر ساتى او پوهه به ستا حِفاظت کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15457, 'Proverbs 2:12', 'Proverbs', 2, 12, '&nbsp;عقل به تا د بدکاره خلقو نه ساتى، او د هغوئ نه چې د چا خبرې چې غلطې دى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15458, 'Proverbs 2:13', 'Proverbs', 2, 13, '&nbsp;چا چې صحيح لاره پرېښې ده او په تيارو کښې تلل کوى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15459, 'Proverbs 2:14', 'Proverbs', 2, 14, '&nbsp;څوک چې د خرابو کارونو په کولو خوشحاليږى او د بدعملو په شرارت خوشحالى کوى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15460, 'Proverbs 2:15', 'Proverbs', 2, 15, '&nbsp;او دغه کسان په کږو وږو سر دى او د هغوئ چال چلن د ټګۍ دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15461, 'Proverbs 2:16', 'Proverbs', 2, 16, '&nbsp;نو هغه به تا د بدکارې ښځې نه وساتى، د هغې زناکارې نه څوک چې په خوږو خبرو تا دوکه کول غواړى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15462, 'Proverbs 2:17', 'Proverbs', 2, 17, '&nbsp;چا چې خپل د ځوانۍ د وخت خاوند پرېښے دے او خپل لوظ يې هېر کړو کوم يې چې د خُدائ پاک په وړاندې کړے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15463, 'Proverbs 2:18', 'Proverbs', 2, 18, '&nbsp;د هغې کور ته تلل مرګ ته دعوت دے، او د هغې د کور لار د قبر لار ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15464, 'Proverbs 2:19', 'Proverbs', 2, 19, '&nbsp;څوک چې هغې له ورشى نو هغه بيا نۀ راواپس کيږى او هغه بيا هيڅکله د ژوند په لاره راتلے نۀ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15465, 'Proverbs 2:20', 'Proverbs', 2, 20, '&nbsp;نو بيا تۀ د ښو خلقو په طريقو تلل کوه او د صادقانو په لارو کښې پاتې شه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15466, 'Proverbs 2:21', 'Proverbs', 2, 21, '&nbsp;نو نېکان به په مُلک کښې اوسيږى، او بې‌داغه خلق به په کښې پاتې شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15467, 'Proverbs 2:22', 'Proverbs', 2, 22, '&nbsp;خو بدعمله به د هغه مُلک نه وشړلے شى، او غداران به ترې د بېخ نه وويستلے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15468, 'Proverbs 3:1', 'Proverbs', 3, 1, '&nbsp;زما زويه، زما لارښودنه مۀ هېروه، خو زما حُکمونه په خپل زړۀ کښې وساته.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15469, 'Proverbs 3:2', 'Proverbs', 3, 2, '&nbsp;زما تعليم به ستا عمر سېوا کړى او خوشحالى به درکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15470, 'Proverbs 3:3', 'Proverbs', 3, 3, '&nbsp;هيڅکله مينه او وفادارى د خپل ځان نه مۀ لرې کوه. دوئ د خپلې غاړې هار کړه او د خپل زړۀ په تخته باندې يې وليکه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15471, 'Proverbs 3:4', 'Proverbs', 3, 4, '&nbsp;نو بيا به تۀ د انسانانو او د خُدائ پاک په نظر کښې محبوبيت او نېک نامى حاصله کړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15472, 'Proverbs 3:5', 'Proverbs', 3, 5, '&nbsp;په خپل ټول زړۀ سره په مالِک خُدائ باندې توکل کوه. او په خپله پوهه باندې تکيه مۀ کوه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15473, 'Proverbs 3:6', 'Proverbs', 3, 6, '&nbsp;چې تۀ هر کار کوې نو په هغې کښې مالِک خُدائ ياد ساته، او هغه به تا ته صحيح لاره ښائى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15474, 'Proverbs 3:7', 'Proverbs', 3, 7, '&nbsp;په خپل عقل باندې مۀ مغروره کېږه، د مالِک خُدائ نه يرېږه او بدعملى پرېږده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15475, 'Proverbs 3:8', 'Proverbs', 3, 8, '&nbsp;نو په دې به ستا بدن رغيږى او ستا هډُوکى به پرې تازه شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15476, 'Proverbs 3:9', 'Proverbs', 3, 9, '&nbsp;په خپل مال دولت سره د مالِک خُدائ عزت کوه، او د خپل ټول فصل په وړومبۍ مېوې سره.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15477, 'Proverbs 3:10', 'Proverbs', 3, 10, '&nbsp;نو بيا به ستا ګودامونه ډک شى او د سر نه به اوړى، او ستا د چاټۍ د خولې نه به نوى مے اوړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15478, 'Proverbs 3:11', 'Proverbs', 3, 11, '&nbsp;زما زويه، د مالِک خُدائ اصلاح مۀ رد کوه او کله چې هغه تا تنبيه کوى په هغې باندې مۀ خفه کېږه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15479, 'Proverbs 3:12', 'Proverbs', 3, 12, '&nbsp;ځکه چې مالِک خُدائ چې چا سره مينه کوى نو هم هغه تنبيه کوى لکه څنګه چې يو پلار هم هغه زوئ تنبيه کوى کوم چې هغۀ ته ګران وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15480, 'Proverbs 3:13', 'Proverbs', 3, 13, '&nbsp;بختور ‎دے هغه څوک چې حِکمت حاصل کړى، او هغه څوک چې پوهه حاصله کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15481, 'Proverbs 3:14', 'Proverbs', 3, 14, '&nbsp;ځکه چې دا د سپينو زرو نه ډېر قيمتى دے او د دې ګټه د سرو زرو نه هم ډېره ښۀ ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15482, 'Proverbs 3:15', 'Proverbs', 3, 15, '&nbsp;دا د قيمتى کاڼو نه هم ګران دے او ستا د خوښې يو څيز هم د دې برابر نۀ دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15483, 'Proverbs 3:16', 'Proverbs', 3, 16, '&nbsp;د عقل په ښى لاس کښې اوږد ژوندون دے، او د هغۀ په ګس لاس کښې عزت او دولت دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15484, 'Proverbs 3:17', 'Proverbs', 3, 17, '&nbsp;د هغۀ لارې برکتى دى، او د هغۀ ټولې لارې پُراَمنه دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15485, 'Proverbs 3:18', 'Proverbs', 3, 18, '&nbsp;حِکمت د هغوئ دپاره د ژوند ونه ده څوک چې هغې ته غاړه ورکوى، بختور دى هغوئ څوک چې هغه راټينګوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15486, 'Proverbs 3:19', 'Proverbs', 3, 19, '&nbsp;مالِک خُدائ د خپل حِکمت په ذريعه د زمکې بنياد کېښودلو، او د خپلې هوښيارتيا په ذريعه يې آسمانونه پېدا کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15487, 'Proverbs 3:20', 'Proverbs', 3, 20, '&nbsp;د هغۀ د حِکمت په وسيله د زمکې د لاندې نه چينې روانې شولې، او د وريځو نه پرخه په زمکه راوورېدله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15488, 'Proverbs 3:21', 'Proverbs', 3, 21, '&nbsp;زما زويه، عدل او تميز په خپل ځان کښې پېدا کړه، او هغه د خپل نظر نه مۀ لرې کوه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15489, 'Proverbs 3:22', 'Proverbs', 3, 22, '&nbsp;دوئ به ستا روح تازه ساتى، او دا به ستا په غاړه د فضل هار وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15490, 'Proverbs 3:23', 'Proverbs', 3, 23, '&nbsp;نو بيا به تۀ په حِفاظت سره په خپله لار روان يې او ستا پښه به تيندک ونۀ خورى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15491, 'Proverbs 3:24', 'Proverbs', 3, 24, '&nbsp;کله چې تۀ څملې، تۀ به نۀ يرېږې، او تۀ به په خوږ خوب اودۀ کېږې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15492, 'Proverbs 3:25', 'Proverbs', 3, 25, '&nbsp;نو د ناګهانى افت نه به نۀ يرېږې او نۀ به د هغه تباهۍ نه يرېږې کومه چې په بدعملو باندې راځى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15493, 'Proverbs 3:26', 'Proverbs', 3, 26, '&nbsp;نو مالِک خُدائ به ستا ډاډ وى، او هغه به ستا پښې په دام کښې د ګېرولو نه وساتى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15494, 'Proverbs 3:27', 'Proverbs', 3, 27, '&nbsp;څوک چې حاجتمند وى د هغوئ سره ښېګړه مۀ پرېږده، کۀ چرې دا کار ستا وس کښې وى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15495, 'Proverbs 3:28', 'Proverbs', 3, 28, '&nbsp;کۀ چرې تۀ اوس د خپل ګاونډى سره مدد کولے شې، نو ورته مۀ وايه چې، ”سبا راشه چې مدد دې وکړم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15496, 'Proverbs 3:29', 'Proverbs', 3, 29, '&nbsp;د خپل ګاونډى خلاف هغۀ ته د نقصان ورکولو منصوبه مۀ جوړوه، څوک چې ستا په خوا کښې اوسيږى او په تا باور کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15497, 'Proverbs 3:30', 'Proverbs', 3, 30, '&nbsp;په يو کس باندې هيڅ بې‌هيڅه اِلزام مۀ لګوه ترڅو چې هغۀ تا ته نقصان نۀ وى درسولے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15498, 'Proverbs 3:31', 'Proverbs', 3, 31, '&nbsp;د ظالم سره سيالى مۀ کوه او مۀ د هغۀ په نقش قدم عمل کوه،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15499, 'Proverbs 3:32', 'Proverbs', 3, 32, '&nbsp;ځکه چې مالِک خُدائ د هغوئ نه نفرت کوى څوک چې بدکاره وى، خو هغه د نېکانو سره دوستانه تعلق ساتى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15500, 'Proverbs 3:33', 'Proverbs', 3, 33, '&nbsp;د بدعمله په کور مالِک خُدائ لعنت ورَوى، خو هغه د صادق په کور باندې برکت ورَوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');